-- Isolated homologation only. Catalog-derived minimal schema; NOT full production migration history.
-- Never run against production. No customer data copied.
BEGIN;
CREATE TABLE public.myryra_finance_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,description text NOT NULL,amount_cents bigint NOT NULL,kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT myryra_finance_entries_amount_cents_check CHECK(amount_cents BETWEEN 1 AND 100000000000),CONSTRAINT myryra_finance_entries_description_check CHECK(char_length(btrim(description)) BETWEEN 1 AND 100),CONSTRAINT myryra_finance_entries_kind_check CHECK(kind IN ('income','expense')));
CREATE TABLE public.myryra_journeys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,title text NOT NULL,description text,status text NOT NULL DEFAULT 'active',visibility text NOT NULL DEFAULT 'private',target_date date,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),confirmation_key uuid,CONSTRAINT myryra_journeys_status_check CHECK(status IN ('active','paused','completed','archived')),CONSTRAINT myryra_journeys_title_check CHECK(char_length(btrim(title)) BETWEEN 1 AND 120),CONSTRAINT myryra_journeys_visibility_check CHECK(visibility IN ('private','shared')));
CREATE TABLE public.mika_teacher_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,journey_id uuid NOT NULL REFERENCES public.myryra_journeys(id) ON DELETE CASCADE,topic text NOT NULL,level text NOT NULL DEFAULT 'iniciante',scheduled_at timestamptz,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT mika_teacher_sessions_id_owner_id_key UNIQUE(id,owner_id),CONSTRAINT mika_teacher_sessions_level_check CHECK(char_length(level) BETWEEN 1 AND 40),CONSTRAINT mika_teacher_sessions_topic_check CHECK(char_length(topic) BETWEEN 1 AND 120),CONSTRAINT mika_teacher_sessions_status_check CHECK(status IN ('active','completed','cancelled')));
ALTER TABLE public.myryra_finance_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.myryra_journeys ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.mika_teacher_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_owner_bootstrap ON public.myryra_finance_entries FOR ALL TO authenticated USING ((SELECT auth.uid())=user_id) WITH CHECK ((SELECT auth.uid())=user_id);
CREATE POLICY journey_owner_bootstrap ON public.myryra_journeys FOR ALL TO authenticated USING ((SELECT auth.uid())=owner_id) WITH CHECK ((SELECT auth.uid())=owner_id);
CREATE POLICY teacher_owner_bootstrap ON public.mika_teacher_sessions FOR ALL TO authenticated USING ((SELECT auth.uid())=owner_id) WITH CHECK ((SELECT auth.uid())=owner_id AND EXISTS(SELECT 1 FROM public.myryra_journeys j WHERE j.id=journey_id AND j.owner_id=(SELECT auth.uid())));
COMMIT;
